package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class SecurityCraftBlastPolicyTest {
 @Test void structuralFamiliesOnly(){for(var name:new String[]{"BaseReinforcedBlock","ReinforcedGlassBlock","ReinforcedPaneBlock","ReinforcedSlabBlock","ReinforcedStairsBlock","ReinforcedWallBlock","ReinforcedFenceBlock","ReinforcedDoorBlock","ReinforcedIronTrapDoorBlock"})assertTrue(SecurityCraftBlastPolicy.buildingClass("net.geforcemods.securitycraft.blocks.reinforced."+name));for(var name:new String[]{"ReinforcedHopperBlock","ReinforcedObserverBlock","ReinforcedDispenserBlock","KeypadBlock","ScannerDoorBlock"})assertFalse(SecurityCraftBlastPolicy.buildingClass("net.geforcemods.securitycraft.blocks.reinforced."+name));assertFalse(SecurityCraftBlastPolicy.buildingClass("other.mod.BaseReinforcedBlock"));}
 @Test void ordinaryMaterialsRemainOrdinaryAtDefaultMultiplier(){for(double n:new double[]{.3,3,5,6,1200})assertEquals(n,SecurityCraftBlastPolicy.resistance(n,6,1,null,null));}
 @Test void multiplierAndBlockOverridesHaveDefinedPrecedence(){assertEquals(6,SecurityCraftBlastPolicy.resistance(9,6,3,10d,2d));assertEquals(20,SecurityCraftBlastPolicy.resistance(9,6,2,10d,null));assertEquals(18,SecurityCraftBlastPolicy.resistance(9,6,2,null,null));}
 @Test void extremeAndInvalidNativeValuesNeverBecomeInfinity(){assertEquals(6,SecurityCraftBlastPolicy.resistance(Double.POSITIVE_INFINITY,6,1,null,null));assertEquals(.3,SecurityCraftBlastPolicy.resistance(Double.NaN,.3,1,null,null));assertEquals(1_000_000,SecurityCraftBlastPolicy.resistance(1_000_000,6,1000,null,null));}
 @Test void zeroResistanceIsSupported(){assertEquals(0,SecurityCraftBlastPolicy.resistance(6,6,0,null,null));assertEquals(0,SecurityCraftBlastPolicy.resistance(6,6,1,null,0d));}
 @Test void malformedOverridesAreRejected(){for(var x:new String[]{"NaN","Infinity","-1","1000001","not-a-number"})assertFalse(SecurityCraftBlastPolicy.number(x));assertTrue(SecurityCraftBlastPolicy.number("0.3"));assertTrue(SecurityCraftBlastPolicy.number("1000000"));}
 @Test void configurationKeysAreValidated(){assertTrue(SecurityCraftBlastConfig.valid("glass=0.3",true,false));assertTrue(SecurityCraftBlastConfig.valid("securitycraft:reinforced_stone=12",false,false));assertTrue(SecurityCraftBlastConfig.valid("securitycraft:reinforced_stone=minecraft:stone",false,true));assertFalse(SecurityCraftBlastConfig.valid("device=3",true,false));assertFalse(SecurityCraftBlastConfig.valid("stone=NaN",true,false));assertFalse(SecurityCraftBlastConfig.valid("securitycraft:stone=",false,true));}
}
